from typing import List

class Solution:
    def isZeroArray(self, nums: List[int], queries: List[List[int]]) -> bool:
        n = len(nums)
        diff = [0] * (n + 1)  # Difference array for range additions

        for l, r in queries:
            diff[l] += 1
            if r + 1 < n:
                diff[r + 1] -= 1

        cover = [0] * n
        curr = 0
        for i in range(n):
            curr += diff[i]
            cover[i] = curr

        for i in range(n):
            if cover[i] < nums[i]:
                return False
        return True
